"""S3 Mock implementation for testing without actual S3 buckets.

This module provides mock implementations of S3 operations that redirect
to local filesystem operations, allowing testing of S3 functionality
without requiring actual S3 infrastructure.
"""

import os
import shutil
import time
import carb
from typing import Tuple, Optional
from urllib.parse import urlparse
from pathlib import Path
from enum import Enum
import sys

from .common import _get_setting


# S3CopyResult enum - must match the one in s3_utils.py
class S3CopyResult(Enum):
    OK = "ok"
    ERROR_ALREADY_EXISTS = "error_already_exists"
    ERROR = "error"


class S3Mock:
    """Mock S3 operations by redirecting to local filesystem."""

    def __init__(self):
        self._enabled = False
        self._mock_root = None
        self._original_functions = {}

    def is_enabled(self) -> bool:
        """Check if S3 mock is enabled via settings."""
        return _get_setting("/exts/omni.kit.registry.nucleus/s3Mock/enabled", False)

    def get_mock_root(self) -> str:
        """Get the root directory for mock S3 storage."""
        return _get_setting("/exts/omni.kit.registry.nucleus/s3Mock/rootPath", "")

    def _s3_url_to_local_path(self, url: str) -> str:
        """Convert S3 URL to local filesystem path."""
        parsed = urlparse(url)
        if parsed.scheme != 's3':
            raise ValueError(f"Not an S3 URL: {url}")

        # Parse S3 URL: s3://endpoint/bucket/path
        endpoint = parsed.netloc
        path_parts = parsed.path.lstrip('/').split('/', 1)
        bucket = path_parts[0] if path_parts else ""
        key = path_parts[1] if len(path_parts) > 1 else ""

        # Build local path: mock_root/endpoint/bucket/key
        local_path = os.path.join(self.get_mock_root(), endpoint, bucket, key)
        return os.path.normpath(local_path)

    def install(self):
        """Install mock functions to replace real S3 operations."""
        if not self.is_enabled():
            carb.log_info("S3 mock not enabled in settings")
            return

        mock_root = self.get_mock_root()
        if not mock_root:
            carb.log_error("S3 mock enabled but rootPath not set in settings")
            return

        # Create mock root directory if it doesn't exist
        os.makedirs(mock_root, exist_ok=True)

        carb.log_warn(f"S3 MOCK ENABLED - All S3 operations will be redirected to: {mock_root}")

        # Import s3_utils module
        from . import s3_utils

        # Store original functions and replace with mocks
        self._original_functions = {
            's3_utils.s3_exists': s3_utils.s3_exists,
            's3_utils.s3_exists_async': s3_utils.s3_exists_async,
            's3_utils.s3_stat': s3_utils.s3_stat,
            's3_utils.s3_stat_async': s3_utils.s3_stat_async,
            's3_utils.s3_delete': s3_utils.s3_delete,
            's3_utils.s3_delete_async': s3_utils.s3_delete_async,
            's3_utils.s3_copy': s3_utils.s3_copy,
            's3_utils.s3_copy_async': s3_utils.s3_copy_async,
            's3_utils.s3_read_file': s3_utils.s3_read_file,
            's3_utils.s3_read_file_async': s3_utils.s3_read_file_async,
            's3_utils.s3_write_file': s3_utils.s3_write_file,
            's3_utils.s3_write_file_async': s3_utils.s3_write_file_async,
            's3_utils.get_s3_client': s3_utils.get_s3_client,
            's3_utils.get_async_s3_client': s3_utils.get_async_s3_client,
        }

        # Replace with mock implementations in s3_utils
        s3_utils.s3_exists = self._mock_s3_exists
        s3_utils.s3_exists_async = self._mock_s3_exists_async
        s3_utils.s3_stat = self._mock_s3_stat
        s3_utils.s3_stat_async = self._mock_s3_stat_async
        s3_utils.s3_delete = self._mock_s3_delete
        s3_utils.s3_delete_async = self._mock_s3_delete_async
        s3_utils.s3_copy = self._mock_s3_copy
        s3_utils.s3_copy_async = self._mock_s3_copy_async
        s3_utils.s3_read_file = self._mock_s3_read_file
        s3_utils.s3_read_file_async = self._mock_s3_read_file_async
        s3_utils.s3_write_file = self._mock_s3_write_file
        s3_utils.s3_write_file_async = self._mock_s3_write_file_async
        s3_utils.get_s3_client = self._mock_get_s3_client
        s3_utils.get_async_s3_client = self._mock_get_async_s3_client

        # Also patch the references in omni_client_utils if it's already imported
        if 'omni.kit.registry.nucleus.utils.omni_client_utils' in sys.modules:
            from . import omni_client_utils
            # Store original references from omni_client_utils
            self._original_functions.update({
                'omni_client_utils.s3_exists': getattr(omni_client_utils, 's3_exists', None),
                'omni_client_utils.s3_exists_async': getattr(omni_client_utils, 's3_exists_async', None),
                'omni_client_utils.s3_stat': getattr(omni_client_utils, 's3_stat', None),
                'omni_client_utils.s3_delete': getattr(omni_client_utils, 's3_delete', None),
                'omni_client_utils.s3_copy': getattr(omni_client_utils, 's3_copy', None),
                'omni_client_utils.s3_copy_async': getattr(omni_client_utils, 's3_copy_async', None),
                'omni_client_utils.s3_read_file': getattr(omni_client_utils, 's3_read_file', None),
                'omni_client_utils.s3_write_file': getattr(omni_client_utils, 's3_write_file', None),
                'omni_client_utils.S3CopyResult': getattr(omni_client_utils, 'S3CopyResult', None),
            })

            # Replace references in omni_client_utils
            omni_client_utils.s3_exists = self._mock_s3_exists
            omni_client_utils.s3_exists_async = self._mock_s3_exists_async
            omni_client_utils.s3_stat = self._mock_s3_stat
            omni_client_utils.s3_delete = self._mock_s3_delete
            omni_client_utils.s3_copy = self._mock_s3_copy
            omni_client_utils.s3_copy_async = self._mock_s3_copy_async
            omni_client_utils.s3_read_file = self._mock_s3_read_file
            omni_client_utils.s3_write_file = self._mock_s3_write_file
            omni_client_utils.S3CopyResult = S3CopyResult

        self._enabled = True

    def uninstall(self):
        """Restore original S3 functions."""
        if not self._enabled:
            return

        from . import s3_utils

        # Restore original functions in s3_utils
        for name, func in self._original_functions.items():
            if name.startswith('s3_utils.') and func is not None:
                setattr(s3_utils, name.replace('s3_utils.', ''), func)

        # Restore original functions in omni_client_utils if it was patched
        if 'omni.kit.registry.nucleus.utils.omni_client_utils' in sys.modules:
            from . import omni_client_utils
            for name, func in self._original_functions.items():
                if name.startswith('omni_client_utils.') and func is not None:
                    setattr(omni_client_utils, name.replace('omni_client_utils.', ''), func)

        self._original_functions.clear()
        self._enabled = False

    # Mock implementations

    def _mock_s3_exists(self, url: str) -> bool:
        """Mock s3_exists by checking local filesystem."""
        carb.log_info(f"S3 MOCK: s3_exists called for {url}")
        try:
            local_path = self._s3_url_to_local_path(url)

            # Check if it's a file
            if os.path.isfile(local_path):
                return True

            # Check if it's a directory or has files with this prefix
            if os.path.isdir(local_path):
                return True

            # Check for files with this as a prefix (S3 directory semantics)
            parent_dir = os.path.dirname(local_path)
            if os.path.exists(parent_dir):
                prefix = os.path.basename(local_path)
                for item in os.listdir(parent_dir):
                    if item.startswith(prefix):
                        return True

            return False
        except Exception as e:
            carb.log_error(f"S3 mock error in exists: {e}")
            return False

    async def _mock_s3_exists_async(self, url: str) -> bool:
        """Mock s3_exists_async - just calls sync version."""
        return self._mock_s3_exists(url)

    def _mock_s3_stat(self, url: str):
        """Mock s3_stat by getting local file stats."""
        try:
            local_path = self._s3_url_to_local_path(url)

            if not os.path.isfile(local_path):
                return False, None

            # Create mock entry matching S3 response
            class MockEntry:
                def __init__(self, path):
                    stat = os.stat(path)
                    self.relative_path = os.path.basename(path)
                    self.size = stat.st_size
                    self.modified_time = stat.st_mtime

            return True, MockEntry(local_path)
        except Exception as e:
            carb.log_error(f"S3 mock error in stat: {e}")
            return False, None

    async def _mock_s3_stat_async(self, url: str):
        """Mock s3_stat_async - just calls sync version."""
        return self._mock_s3_stat(url)

    def _mock_s3_delete(self, url: str) -> bool:
        """Mock s3_delete by deleting local file."""
        try:
            local_path = self._s3_url_to_local_path(url)
            if os.path.exists(local_path):
                if os.path.isfile(local_path):
                    os.remove(local_path)
                else:
                    shutil.rmtree(local_path)
            return True
        except Exception as e:
            carb.log_error(f"S3 mock error in delete: {e}")
            return False

    async def _mock_s3_delete_async(self, url: str) -> bool:
        """Mock s3_delete_async - just calls sync version."""
        return self._mock_s3_delete(url)

    def _mock_s3_copy(self, src: str, dst: str, check_exists: bool = False) -> S3CopyResult:
        """Mock s3_copy by copying files locally."""
        try:
            from . import s3_utils

            # Handle local to S3 copy
            if s3_utils.is_s3_url(dst) and not s3_utils.is_s3_url(src):
                local_dst = self._s3_url_to_local_path(dst)

                if check_exists and os.path.exists(local_dst):
                    return S3CopyResult.ERROR_ALREADY_EXISTS

                os.makedirs(os.path.dirname(local_dst), exist_ok=True)
                shutil.copy2(src, local_dst)
                return S3CopyResult.OK

            # Handle S3 to local copy
            elif s3_utils.is_s3_url(src) and not s3_utils.is_s3_url(dst):
                local_src = self._s3_url_to_local_path(src)

                if not os.path.exists(local_src):
                    return S3CopyResult.ERROR

                if check_exists and os.path.exists(dst):
                    return S3CopyResult.ERROR_ALREADY_EXISTS

                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy2(local_src, dst)
                return S3CopyResult.OK

            # Handle S3 to S3 copy
            elif s3_utils.is_s3_url(src) and s3_utils.is_s3_url(dst):
                local_src = self._s3_url_to_local_path(src)
                local_dst = self._s3_url_to_local_path(dst)

                if not os.path.exists(local_src):
                    return S3CopyResult.ERROR

                if check_exists and os.path.exists(local_dst):
                    return S3CopyResult.ERROR_ALREADY_EXISTS

                os.makedirs(os.path.dirname(local_dst), exist_ok=True)
                shutil.copy2(local_src, local_dst)
                return S3CopyResult.OK

            return S3CopyResult.ERROR
        except Exception as e:
            carb.log_error(f"S3 mock error in copy: {e}")
            return S3CopyResult.ERROR

    async def _mock_s3_copy_async(self, src: str, dst: str, check_exists: bool = False) -> S3CopyResult:
        """Mock s3_copy_async - just calls sync version."""
        return self._mock_s3_copy(src, dst, check_exists)

    def _mock_s3_read_file(self, url: str) -> Tuple[bool, bytes]:
        """Mock s3_read_file by reading local file."""
        carb.log_info(f"S3 MOCK: s3_read_file called for {url}")
        try:
            local_path = self._s3_url_to_local_path(url)
            if not os.path.exists(local_path):
                return False, None

            with open(local_path, 'rb') as f:
                content = f.read()
            return True, content
        except Exception as e:
            carb.log_error(f"S3 mock error in read_file: {e}")
            return False, None

    async def _mock_s3_read_file_async(self, url: str) -> Tuple[bool, bytes]:
        """Mock s3_read_file_async - just calls sync version."""
        return self._mock_s3_read_file(url)

    def _mock_s3_write_file(self, url: str, content: bytes) -> bool:
        """Mock s3_write_file by writing to local file."""
        carb.log_info(f"S3 MOCK: s3_write_file called for {url}")
        try:
            local_path = self._s3_url_to_local_path(url)
            os.makedirs(os.path.dirname(local_path), exist_ok=True)

            with open(local_path, 'wb') as f:
                f.write(content)
            return True
        except Exception as e:
            carb.log_error(f"S3 mock error in write_file: {e}")
            return False

    async def _mock_s3_write_file_async(self, url: str, content: bytes) -> bool:
        """Mock s3_write_file_async - just calls sync version."""
        return self._mock_s3_write_file(url, content)

    def _mock_get_s3_client(self, endpoint: str):
        """Mock get_s3_client - returns None since we don't need a real client."""
        carb.log_info(f"Mock get_s3_client called for {endpoint}")
        return None

    def _mock_get_async_s3_client(self, endpoint: str):
        """Mock get_async_s3_client - returns a mock context manager."""
        carb.log_info(f"Mock get_async_s3_client called for {endpoint}")

        class MockAsyncS3Client:
            async def __aenter__(self):
                return None

            async def __aexit__(self, exc_type, exc_val, exc_tb):
                pass

        return MockAsyncS3Client()


# Global instance
_s3_mock = S3Mock()


def install_s3_mock():
    """Install S3 mock if enabled in settings."""
    _s3_mock.install()


def uninstall_s3_mock():
    """Uninstall S3 mock and restore original functions."""
    _s3_mock.uninstall()
